create table public.deal_stages(id text primary key,name text not null,sort_order integer not null unique,probability integer not null default 0,terminal boolean not null default false);insert into public.deal_stages(id,name,sort_order,probability,terminal)values('new_lead','New Lead',0,5,false),('qualified','Qualified',1,15,false),('meeting_scheduled','Meeting Scheduled',2,20,false),('site_visit_scheduled','Site Visit Scheduled',3,30,false),('site_visit_completed','Site Visit Completed',4,40,false),('proposal_sent','Proposal Sent',5,50,false),('negotiation','Negotiation',6,65,false),('booking','Booking',7,75,false),('agreement','Agreement',8,85,false),('payment_pending','Payment Pending',9,90,false),('registration','Registration',10,95,false),('completed','Completed',11,100,true),('lost','Lost',12,0,true),('support','Support',13,100,false);
create table public.deals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),reference text not null,name text not null,lead_id uuid references public.leads(id),property_id uuid not null references public.properties(id),stage_id text not null references public.deal_stages(id),status text not null default'open',deal_type text not null default'sale',value numeric(18,2)not null,currency char(3)not null,probability integer not null check(probability between 0 and 100),expected_closing date,assigned_agent_id uuid references auth.users(id),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(organization_id,workspace_id,reference));
create table public.deal_site_visits(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),starts_at timestamptz not null,outcome text,notes text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.deal_offers(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),offer_number text not null,amount numeric(18,2)not null,discount numeric(7,4),currency char(3)not null,status text not null,expires_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.deal_payments(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),payment_type text not null,amount numeric(18,2)not null,currency char(3)not null,due_at timestamptz,paid_at timestamptz,status text not null default'pending',created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.deal_commissions(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),commission_type text not null,amount numeric(18,2)not null,currency char(3)not null,status text not null,created_at timestamptz not null default now());
create table public.deal_notes(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),body text not null,pinned boolean not null default false,private boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.deal_saved_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),user_id uuid not null references auth.users(id),name text not null,query jsonb not null default'{}',created_at timestamptz not null default now(),unique(workspace_id,user_id,name));
create index deals_pipeline_idx on public.deals(organization_id,workspace_id,stage_id,updated_at desc)where deleted_at is null;
alter table public.deal_stages enable row level security;alter table public.deals enable row level security;alter table public.deal_site_visits enable row level security;alter table public.deal_offers enable row level security;alter table public.deal_payments enable row level security;alter table public.deal_commissions enable row level security;alter table public.deal_notes enable row level security;alter table public.deal_saved_views enable row level security;
create policy "deal_stages_authenticated_read" on public.deal_stages for select to authenticated using(true);
create policy "deals_workspace_read" on public.deals for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deals.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_site_visits_workspace_read" on public.deal_site_visits for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_site_visits.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_offers_workspace_read" on public.deal_offers for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_offers.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_payments_workspace_read" on public.deal_payments for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_payments.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_commissions_workspace_read" on public.deal_commissions for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_commissions.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_notes_workspace_read" on public.deal_notes for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_notes.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "deal_saved_views_owner_read" on public.deal_saved_views for select to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=deal_saved_views.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create or replace function public.can_manage_deal(p_workspace uuid,p_assigned uuid default null)returns boolean language sql stable security definer set search_path=public as $$select current_workspace_role(p_workspace)in('organization_owner','organization_admin','sales_manager','branch_manager')or(current_workspace_role(p_workspace)='agent'and p_assigned=auth.uid())$$;
create or replace function public.create_deal(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_manage_deal(p_workspace_id)then raise exception'insufficient deal permission';end if;insert into deals(organization_id,workspace_id,reference,name,lead_id,property_id,stage_id,value,currency,probability,expected_closing,assigned_agent_id,created_by,updated_by)select v_org,p_workspace_id,p_input->>'reference',p_input->>'name',nullif(p_input->>'leadId','')::uuid,(p_input->>'propertyId')::uuid,p_input->>'stageId',(p_input->>'value')::numeric,upper(p_input->>'currency'),(p_input->>'probability')::integer,nullif(p_input->>'expectedClosing','')::date,nullif(p_input->>'assignedAgentId','')::uuid,auth.uid(),auth.uid()where exists(select 1 from properties p where p.id=(p_input->>'propertyId')::uuid and p.organization_id=v_org and p.workspace_id=p_workspace_id and p.deleted_at is null)returning id into v_id;if v_id is null then raise exception'invalid property';end if;return v_id;end$$;
create or replace function public.update_deal(p_deal_id uuid,p_expected_version integer,p_input jsonb)returns void language plpgsql security definer set search_path=public as $$declare d deals%rowtype;begin select*into d from deals where id=p_deal_id and deleted_at is null for update;if not found or not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient deal permission';end if;if d.version<>p_expected_version then raise exception'deal changed by another user';end if;update deals set name=p_input->>'name',reference=p_input->>'reference',lead_id=nullif(p_input->>'leadId','')::uuid,property_id=(p_input->>'propertyId')::uuid,stage_id=p_input->>'stageId',value=(p_input->>'value')::numeric,currency=upper(p_input->>'currency'),probability=(p_input->>'probability')::integer,expected_closing=nullif(p_input->>'expectedClosing','')::date,assigned_agent_id=case when current_workspace_role(d.workspace_id)<>'agent'then nullif(p_input->>'assignedAgentId','')::uuid else d.assigned_agent_id end,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_deal_id;end$$;
create or replace function public.move_deal_stage(p_deal_id uuid,p_expected_version integer,p_stage_id text)returns void language plpgsql security definer set search_path=public as $$declare d deals%rowtype;begin select*into d from deals where id=p_deal_id and deleted_at is null for update;if not found or not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient deal permission';end if;if d.version<>p_expected_version then raise exception'deal changed by another user';end if;if not exists(select 1 from deal_stages where id=p_stage_id)then raise exception'invalid stage';end if;update deals set stage_id=p_stage_id,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_deal_id;end$$;
create or replace function public.archive_deal(p_deal_id uuid)returns void language plpgsql security definer set search_path=public as $$declare d deals%rowtype;begin select*into d from deals where id=p_deal_id and deleted_at is null;if not found or current_workspace_role(d.workspace_id)not in('organization_owner','organization_admin','sales_manager','branch_manager')then raise exception'insufficient archive permission';end if;update deals set deleted_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_deal_id;end$$;
create or replace function public.create_offer(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare d deals%rowtype;v_id uuid;begin select*into d from deals where id=(p_input->>'dealId')::uuid and deleted_at is null;if not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient permission';end if;insert into deal_offers(deal_id,organization_id,workspace_id,offer_number,amount,discount,currency,status,expires_at,created_by)values(d.id,d.organization_id,d.workspace_id,p_input->>'offerNumber',(p_input->>'amount')::numeric,nullif(p_input->>'discount','')::numeric,upper(p_input->>'currency'),p_input->>'status',nullif(p_input->>'expiresAt','')::timestamptz,auth.uid())returning id into v_id;return v_id;end$$;
create or replace function public.create_payment(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare d deals%rowtype;v_id uuid;begin select*into d from deals where id=(p_input->>'dealId')::uuid and deleted_at is null;if not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient permission';end if;insert into deal_payments(deal_id,organization_id,workspace_id,payment_type,amount,currency,due_at,paid_at,created_by)values(d.id,d.organization_id,d.workspace_id,p_input->>'paymentType',(p_input->>'amount')::numeric,upper(p_input->>'currency'),nullif(p_input->>'dueAt','')::timestamptz,nullif(p_input->>'paidAt','')::timestamptz,auth.uid())returning id into v_id;return v_id;end$$;
create or replace function public.create_commission(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare d deals%rowtype;v_id uuid;begin select*into d from deals where id=(p_input->>'dealId')::uuid and deleted_at is null;if not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient permission';end if;insert into deal_commissions(deal_id,organization_id,workspace_id,commission_type,amount,currency,status)values(d.id,d.organization_id,d.workspace_id,p_input->>'commissionType',(p_input->>'amount')::numeric,upper(p_input->>'currency'),p_input->>'status')returning id into v_id;return v_id;end$$;
create or replace function public.create_visit(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare d deals%rowtype;v_id uuid;begin select*into d from deals where id=(p_input->>'dealId')::uuid and deleted_at is null;if not can_manage_deal(d.workspace_id,d.assigned_agent_id)then raise exception'insufficient permission';end if;insert into deal_site_visits(deal_id,organization_id,workspace_id,starts_at,outcome,notes,created_by)values(d.id,d.organization_id,d.workspace_id,(p_input->>'startsAt')::timestamptz,nullif(p_input->>'outcome',''),nullif(p_input->>'notes',''),auth.uid())returning id into v_id;return v_id;end$$;
